import { RoxyPanchangTable as Element } from '@roxyapi/ui-react';
import type { ComponentProps } from 'react';

export type RoxyPanchangTableProps = ComponentProps<typeof Element>;

export function RoxyPanchangTable(props: RoxyPanchangTableProps) {
	return <Element {...props} />;
}

export default RoxyPanchangTable;
